entries.value_conv_text:
$val =~ /^(\d{4})(\d{2})(\d{2})$/ and return "$1:$2:$3";
# Optio A10 and A20 leave "200" off the year
$val =~ /^(\d)(\d{2})(\d{2})$/ and return "200$1:$2:$3";
return "Unknown ($val)";

return 0 unless $val;
$val = -3 if $val == 29;  # -3 is stored as 0x1d
return 2**($val/16 + 4);

my @v = split(' ',$val);
$v[0] &= 0x0f;
$v[1] = $v[2] * 256 + $v[3]; # (always high byte first)
return "$v[0] $v[1]";

my @v = split(' ',$val);
$v[0] &= 0x0f;
$v[1] = $v[2] * 256 + $v[3]; # (always high byte first)
return "$v[0] $v[1]";

my @v = split(' ',$val);
$v[0] &= 0x0f;
$v[1] = $v[2] * 256 + $v[3]; # (always high byte first)
return "$v[0] $v[1]";

my @v = split(' ',$val);
$v[0] &= 0x0f;
$v[1] = $v[3] * 256 + $v[4]; # (always high byte first)
return "$v[0] $v[1]";
